const searchIssues = `-- name: SearchIssues :many
SELECT i.project_id, p.name AS project_name, COALESCE(p.issue_key, '')::text AS issue_key,
       i.number, i.title, i.status, i.priority, i.type_id,
       COALESCE(p.issue_key_digits, o.issue_key_digits)::int AS digits
FROM issues i
JOIN projects p ON p.id = i.project_id
JOIN organizations o ON o.id = p.org_id
WHERE p.org_id = $1
  AND ($2::uuid IS NULL OR i.project_id = $2::uuid)
  AND (NOT $3::bool
       OR ($4::text <> '' AND i.search @@ to_tsquery('simple', $4::text))
       OR (i.number = $5::int AND ($6::text = '' OR p.issue_key = $6::text
           OR EXISTS (SELECT 1 FROM issue_key_aliases k WHERE k.project_id = p.id AND k.key = $6::text)))
       OR ($7::text <> '' AND (p.issue_key = $7::text
           OR EXISTS (SELECT 1 FROM issue_key_aliases k WHERE k.project_id = p.id AND k.key = $7::text))))
ORDER BY (i.status IN ('shipped', 'cancelled')), i.updated_at DESC
LIMIT $8
`

