const setIssueTypeArchived = `-- name: SetIssueTypeArchived :execrows
UPDATE issue_types SET archived_at = CASE WHEN $1::bool THEN COALESCE(archived_at, NOW()) END
WHERE id = $2 AND org_id = $3
`

type SetIssueTypeArchivedParams struct {
	Archived bool        `json:"archived"`
	ID       pgtype.UUID `json:"id"`
	OrgID    pgtype.UUID `json:"org_id"`
}

func (q *Queries) SetIssueTypeArchived(ctx context.Context, arg SetIssueTypeArchivedParams) (int64, error) {
	result, err := q.db.Exec(ctx, setIssueTypeArchived, arg.Archived, arg.ID, arg.OrgID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

