const updateIssue = `-- name: UpdateIssue :exec
UPDATE issues
SET title = $1, description = $2, priority = $3,
    assignee_id = $4, type_id = $5, parent_id = $6,
    cycle_id = $7, start_on = $8, due_on = $9, estimate = $10,
    status_changed_at = CASE WHEN status <> $11 THEN NOW() ELSE status_changed_at END,
    status = $11, updated_at = NOW()
WHERE id = $12
`

type UpdateIssueParams struct {
	Title       string      `json:"title"`
	Description string      `json:"description"`
	Priority    string      `json:"priority"`
	AssigneeID  pgtype.UUID `json:"assignee_id"`
	TypeID      pgtype.UUID `json:"type_id"`
	ParentID    pgtype.UUID `json:"parent_id"`
	CycleID     pgtype.UUID `json:"cycle_id"`
	StartOn     pgtype.Date `json:"start_on"`
	DueOn       pgtype.Date `json:"due_on"`
	Estimate    *int16      `json:"estimate"`
	Status      string      `json:"status"`
	ID          pgtype.UUID `json:"id"`
}

// The service merges what changed into the row it read; status_changed_at
// moves only when the status does.
func (q *Queries) UpdateIssue(ctx context.Context, arg UpdateIssueParams) error {
	_, err := q.db.Exec(ctx, updateIssue,
		arg.Title,
		arg.Description,
		arg.Priority,
		arg.AssigneeID,
		arg.TypeID,
		arg.ParentID,
		arg.CycleID,
		arg.StartOn,
		arg.DueOn,
		arg.Estimate,
		arg.Status,
		arg.ID,
	)
	return err
}

